// js
const employment = ctx.subject.employment;
const terms = employment.terms;
const facts = get(employment, 'employee_extension_data', {});
const unit = get(terms, 'rate.unit', 'MONTHLY');
const partTime = get(employment, 'engagement', 'EMPLOYEE') === 'PART_TIME';
const normal = Number(
	get(
		terms,
		'normal_hours_per_day',
		partTime
			? ctx.lookup.part_time_hours_factor * 8
			: 8
	)
);
const full = partTime
	? Number(
			get(facts, 'comparable_full_time_hours_per_day', 8)
		)
	: normal;
const orpDay = ctx.day_rate;
const days = get(ctx, 'work.days', []);
// Every holiday kind except MAKEUP_WORKDAY earns the premium; a makeup workday is a plain working day.
const holiday = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const other = unit === 'DAILY' || unit === 'HOURLY';
const rest = days.filter((day) => get(day, 'day_type', 'WORK') === 'REST' && !holiday(day));
const worked = (day) => Math.min(Number(get(day, 'worked_hours', 0)), normal);
const owed = (day) => {
	if (worked(day) <= 0) return 0;
	if (worked(day) <= normal * ctx.lookup.half_day_hours_factor)
		return other ? ctx.lookup.other_half_day : ctx.lookup.monthly_half_day;
	return other ? ctx.lookup.other_full_day : ctx.lookup.monthly_full_day;
};
// EA ss.7, 7A: the employer's rest-day hourly multiple stands on each day it pays more than s.60(3).
const multiple = Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0));
if (multiple <= 0) return sum(rest.map(owed)) * orpDay;
return sum(rest.map((day) => Math.max(owed(day) * orpDay, worked(day) * multiple * ctx.hour_rate)));

